sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float amount;
uniform float grain;
float hash(float2 p) { p = fract(p * float2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }
half4 main(float2 coord) {
    half4 c = unpremul(image.eval(coord));
    half n = half(hash(floor(coord / max(grain, 0.5)) + floor(time * 30) * 17.0));
    return half4(mix(c.rgb, half3(n), half(amount)) * c.a, c.a);
}
